using Servicio.RetazoMarket.Business.DTOs.Proveedor;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.Business.Mappers;
public static class ProveedorBusinessMapper { public static ProveedorDataModel ToDataModel(CrearProveedorRequest r)=>new(){codigo_proveedor=r.codigo_proveedor.Trim().ToUpperInvariant(),prov_nombre=r.prov_nombre.Trim(),prov_telefono=r.prov_telefono.Trim(),prov_correo=r.prov_correo.Trim().ToLowerInvariant(),prov_direccion=r.prov_direccion.Trim(),prov_estado=r.prov_estado.Trim().ToUpperInvariant()}; public static ProveedorDataModel ToDataModel(ActualizarProveedorRequest r)=>new(){id_proveedor=r.id_proveedor,codigo_proveedor=r.codigo_proveedor.Trim().ToUpperInvariant(),prov_nombre=r.prov_nombre.Trim(),prov_telefono=r.prov_telefono.Trim(),prov_correo=r.prov_correo.Trim().ToLowerInvariant(),prov_direccion=r.prov_direccion.Trim(),prov_estado=r.prov_estado.Trim().ToUpperInvariant()}; public static ProveedorResponse ToResponse(ProveedorDataModel m)=>new(){id_proveedor=m.id_proveedor,codigo_proveedor=m.codigo_proveedor,prov_nombre=m.prov_nombre,prov_telefono=m.prov_telefono,prov_correo=m.prov_correo,prov_direccion=m.prov_direccion,prov_estado=m.prov_estado}; }
